package edu.atlas.campusos.web;

import edu.atlas.campusos.model.*; import edu.atlas.campusos.repo.*; import edu.atlas.campusos.service.*;
import org.springframework.data.domain.Sort;
import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import java.util.stream.*;

@RestController @RequestMapping("/api")
public class ApiController {
    private final RoomRepository rooms;private final SessionRepository sessions;private final AllocationRepository allocations;private final SpaceAssignmentRepository spaceAssignments;private final DivisionRepository divisions;private final TimePeriodRepository periods;private final AllocationService allocator;private final BenchmarkService benchmarks;
    public ApiController(RoomRepository r,SessionRepository s,AllocationRepository a,SpaceAssignmentRepository sa,DivisionRepository d,TimePeriodRepository p,AllocationService as,BenchmarkService bs){rooms=r;sessions=s;allocations=a;spaceAssignments=sa;divisions=d;periods=p;allocator=as;benchmarks=bs;}
    @GetMapping("/structure") public Map<String,Object> structure(){int total=136;return Map.of("schools",Curriculum.SCHOOLS.stream().map(s->Map.of("code",s.code(),"name",s.name(),"weight",s.weight(),"proportion",(double)s.weight()/total,"duration",s.duration(),"programs",s.programs())).toList(),"divisions",divisions.findAll());}
    @GetMapping("/rooms") public List<Room> rooms(){return rooms.findAll(Sort.by("floor","name"));}
    @PostMapping("/rooms") public Room addRoom(@RequestBody Room r){validateRoom(r);if(rooms.existsByNameIgnoreCase(r.name))throw new IllegalArgumentException("A classroom with that name already exists.");r.id=null;return rooms.save(r);}
    @PutMapping("/rooms/{id}") public Room updateRoom(@PathVariable long id,@RequestBody Room r){Room old=rooms.findById(id).orElseThrow(()->new NoSuchElementException("Classroom not found."));validateRoom(r);if(rooms.findAll().stream().anyMatch(x->!x.id.equals(id)&&x.name.equalsIgnoreCase(r.name)))throw new IllegalArgumentException("A classroom with that name already exists.");old.name=r.name;old.floor=r.floor;old.capacity=r.capacity;old.available=r.available;return rooms.save(old);}
    @DeleteMapping("/rooms/{id}") public Map<String,Object> deleteRoom(@PathVariable long id){Room r=rooms.findById(id).orElseThrow();if(allocations.findAll().stream().anyMatch(a->Objects.equals(a.assignedRoom,r.name))||spaceAssignments.findAll().stream().anyMatch(a->Objects.equals(a.assignedRoom,r.name)))throw new IllegalStateException("This room appears in allocation results. Remove or replace those results before deleting it.");rooms.delete(r);return Map.of("deleted",true);}
    private void validateRoom(Room r){if(r.name==null||r.name.isBlank())throw new IllegalArgumentException("Classroom name is required.");if(r.floor<1||r.floor>7)throw new IllegalArgumentException("Floor must be between 1 and 7.");if(r.capacity<=0)throw new IllegalArgumentException("Capacity must be positive.");}
    @GetMapping("/sessions") public List<ClassSession> listSessions(@RequestParam(required=false)String school,@RequestParam(required=false)String program,@RequestParam(required=false)Integer year,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){return sessions.findAll(Sort.by("date","startTime")).stream().filter(x->school==null||x.school.equalsIgnoreCase(school)).filter(x->program==null||x.program.equals(program)).filter(x->year==null||x.academicYear==year).filter(x->date==null||x.date.equals(date)).toList();}
    @PostMapping("/sessions") public ClassSession addSession(@RequestBody ClassSession s){validateSession(s);s.id=null;if(sessions.existsByClassIdAndDateAndStartTimeAndDivision(s.classId,s.date,s.startTime,s.division))throw new IllegalArgumentException("A matching class record already exists.");return sessions.save(s);}
    @PutMapping("/sessions/{id}") public ClassSession updateSession(@PathVariable long id,@RequestBody ClassSession s){ClassSession old=sessions.findById(id).orElseThrow();validateSession(s);old.classId=s.classId;old.school=s.school;old.program=s.program;old.academicYear=s.academicYear;old.division=s.division;old.studentCount=s.studentCount;old.date=s.date;old.startTime=s.startTime;old.endTime=s.endTime;return sessions.save(old);}
    @DeleteMapping("/sessions/{id}") public Map<String,Object> deleteSession(@PathVariable long id){ClassSession s=sessions.findById(id).orElseThrow();allocations.deleteBySessionIdIn(List.of(id));sessions.delete(s);return Map.of("deleted",true);}
    private void validateSession(ClassSession s){if(s.classId==null||s.classId.isBlank()||s.division==null||s.division.isBlank())throw new IllegalArgumentException("Class ID and division are required.");if(!Curriculum.hasProgram(s.school,s.program))throw new IllegalArgumentException("School and program do not match the academic structure.");if(s.academicYear<1||s.academicYear>Curriculum.duration(s.school))throw new IllegalArgumentException("Academic year is outside the program duration.");if(s.studentCount<0)throw new IllegalArgumentException("Student count cannot be negative.");if(s.date==null||s.startTime==null||s.endTime==null||s.startTime.getSecond()!=0||s.startTime.getNano()!=0||s.endTime.getSecond()!=0||s.endTime.getNano()!=0||!s.startTime.isBefore(s.endTime))throw new IllegalArgumentException("Enter a valid date and minute-aligned times with start before end.");}
    @PostMapping("/divisions") public Division addDivision(@RequestBody Division d){if(!Curriculum.hasProgram(d.school,d.program))throw new IllegalArgumentException("School and program do not match.");if(d.academicYear<1||d.academicYear>Curriculum.duration(d.school))throw new IllegalArgumentException("Year is outside the program duration.");if(d.name==null||d.name.isBlank()||d.actualStudents!=null&&d.actualStudents<0)throw new IllegalArgumentException("Enter a division name and a non-negative actual enrollment.");d.id=null;return divisions.save(d);}
    @PutMapping("/divisions/{id}") public Division updateDivision(@PathVariable long id,@RequestBody Division d){Division old=divisions.findById(id).orElseThrow();if(d.actualStudents!=null&&d.actualStudents<0)throw new IllegalArgumentException("Enrollment cannot be negative.");old.school=d.school;old.program=d.program;old.academicYear=d.academicYear;old.name=d.name;old.actualStudents=d.actualStudents;return divisions.save(old);}
    @DeleteMapping("/divisions/{id}") public Map<String,Object> deleteDivision(@PathVariable long id){divisions.deleteById(id);return Map.of("deleted",true);}
    @PostMapping("/allocate") public Map<String,Object> run(@RequestBody Map<String,Object> body){LocalDate date=LocalDate.parse(String.valueOf(body.get("date")));boolean replace=Boolean.TRUE.equals(body.get("replaceExisting"));return allocator.run(date,replace);}
    @GetMapping("/preflight") public Map<String,Object> preflight(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){List<ClassSession> day=sessions.findByDate(date);List<Room> allRooms=rooms.findAll();List<TimePeriod> active=periods.findAll().stream().filter(p->p.active).toList();int maxCapacity=allRooms.stream().filter(r->r.available).mapToInt(r->r.capacity).max().orElse(0);List<Map<String,Object>> issues=new ArrayList<>();for(ClassSession c:day){boolean mapped=active.stream().anyMatch(p->p.startTime.equals(c.startTime)&&p.endTime.equals(c.endTime));if(!mapped)issues.add(Map.of("severity","warning","kind","unmapped","title",c.classId+" has no active timetable period","detail",c.startTime+"–"+c.endTime+" does not exactly match an active period.","action","Review periods","page","timetable","classId",c.classId));if(maxCapacity>0&&c.studentCount>maxCapacity)issues.add(Map.of("severity","warning","kind","oversize","title",c.classId+" exceeds room capacity","detail",c.studentCount+" students; the largest available room seats "+maxCapacity+".","action","Review rooms","page","rooms","classId",c.classId));}List<Room> unavailable=allRooms.stream().filter(r->!r.available).toList();if(!unavailable.isEmpty())issues.add(Map.of("severity","info","kind","unavailable","title",unavailable.size()+" classroom"+(unavailable.size()==1?" is":"s are")+" marked unavailable","detail",String.join(", ",unavailable.stream().map(r->r.name).toList()),"action","Review rooms","page","rooms"));for(SpaceAssignment a:spaceAssignments.findByDate(date).stream().filter(x->"Unallocated".equals(x.status)).toList()){String advice=(a.reason!=null&&a.reason.toLowerCase().contains("occupied"))?"Try a different start/end time or clear the preferred room/floor.":"Check the requested headcount and preferred room/floor; try another time if needed.";issues.add(Map.of("severity","warning","kind","booking","title",a.title+" could not be placed","detail",(a.reason==null?"No room was assigned.":a.reason)+" "+advice,"action","Review booking","page","bookings","classId",a.type+"-"+a.requestId));}return Map.of("date",date,"classes",day.size(),"availableRooms",allRooms.stream().filter(r->r.available).count(),"issues",issues,"ready",issues.stream().noneMatch(i->"warning".equals(i.get("severity"))));}
    @GetMapping("/room-finder") public Map<String,Object> roomFinder(@RequestParam String q){String text=q.toLowerCase(Locale.ROOT);java.util.regex.Matcher n=java.util.regex.Pattern.compile("(\\d+)\\s*(?:students?|people|seats)?").matcher(text);if(!n.find())throw new IllegalArgumentException("Include a headcount, such as 45 students.");int people=Integer.parseInt(n.group(1)),floor=0;java.util.regex.Matcher f=java.util.regex.Pattern.compile("(?:floor|level)\\s*(\\d+)").matcher(text);if(f.find())floor=Integer.parseInt(f.group(1));LocalDate date=LocalDate.now();String[] days={"monday","tuesday","wednesday","thursday","friday","saturday","sunday"};for(int i=0;i<7;i++)if(text.contains(days[i])){int d=(DayOfWeek.of(i+1).getValue()-date.getDayOfWeek().getValue()+7)%7;date=date.plusDays(d==0?7:d);break;}java.util.regex.Matcher t=java.util.regex.Pattern.compile("(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)?\\s*(?:-|to|–)\\s*(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)").matcher(text);if(!t.find())throw new IllegalArgumentException("Include a time range, like 3-5 PM.");int h1=Integer.parseInt(t.group(1)),m1=t.group(2)==null?0:Integer.parseInt(t.group(2)),h2=Integer.parseInt(t.group(4)),m2=t.group(5)==null?0:Integer.parseInt(t.group(5));String mer=t.group(3)==null?t.group(6):t.group(3);if("pm".equals(mer)&&h1<12)h1+=12;if("am".equals(mer)&&h1==12)h1=0;if("pm".equals(t.group(6))&&h2<12)h2+=12;if("am".equals(t.group(6))&&h2==12)h2=0;LocalTime start=LocalTime.of(h1,m1),end=LocalTime.of(h2,m2);if(!start.isBefore(end))throw new IllegalArgumentException("End time must follow start time.");List<ClassSession> day=sessions.findByDate(date);Map<String,SegmentTree> trees=new HashMap<>();rooms.findAll().forEach(r->trees.put(r.name,new SegmentTree()));for(ClassSession c:day){Allocation a=allocations.findAll().stream().filter(x->Objects.equals(x.sessionId,c.id)&&"Allocated".equals(x.status)).findFirst().orElse(null);if(a!=null&&trees.containsKey(a.assignedRoom))trees.get(a.assignedRoom).occupy(c.startTime.getHour()*60+c.startTime.getMinute(),c.endTime.getHour()*60+c.endTime.getMinute());}int from=start.getHour()*60+start.getMinute(),to=end.getHour()*60+end.getMinute(),pref=floor;List<Map<String,Object>> found=new ArrayList<>();for(Room r:rooms.findAll())if(r.available&&r.capacity>=people&&trees.get(r.name).isFree(from,to)){Map<String,Object>x=new LinkedHashMap<>();x.put("room",r.name);x.put("floor",r.floor);x.put("capacity",r.capacity);x.put("spare",r.capacity-people);x.put("rank",(pref==0||pref==r.floor?0:100000)+r.capacity-people);found.add(x);}found.sort(Comparator.comparingInt(x->(Integer)x.get("rank")));return Map.of("date",date,"people",people,"start",start,"end",end,"floor",floor,"matches",found);}
    @GetMapping("/weekly-insights") public Map<String,Object> weeklyInsights(){List<Allocation> allocated=allocations.findAll().stream().filter(a->"Allocated".equals(a.status)&&a.assignedRoom!=null).toList();List<ClassSession> classes=sessions.findAll();String[] weekdays={"Monday","Tuesday","Wednesday","Thursday","Friday"};List<Map<String,Object>> heat=new ArrayList<>();for(Room room:rooms.findAll()){for(int d=1;d<=5;d++)for(int hour=7;hour<21;hour++){final int day=d,h=hour;List<Allocation> hits=allocated.stream().filter(a->room.name.equals(a.assignedRoom)&&a.date!=null&&a.date.getDayOfWeek().getValue()==day&&overlapsHour(a.timeLabel,h)).toList();long observed=classes.stream().filter(c->c.date.getDayOfWeek().getValue()==day&&c.startTime.getHour()<=h&&c.endTime.getHour()>h).count();int percent=(int)Math.round(100.0*hits.size()/Math.max(1,classes.stream().filter(c->c.date.getDayOfWeek().getValue()==day).map(c->c.date).distinct().count()));heat.add(Map.of("room",room.name,"floor",room.floor,"day",weekdays[day-1],"hour",hour,"utilization",Math.min(100,percent),"bookings",hits.size(),"observedClasses",observed));}}Map<String,Object> insights=new LinkedHashMap<>();for(int d=1;d<=5;d++){final int day=d;Map<String,List<ClassSession>> groups=classes.stream().filter(c->c.date.getDayOfWeek().getValue()==day).collect(Collectors.groupingBy(c->c.startTime+"–"+c.endTime));for(var entry:groups.entrySet()){List<ClassSession> group=entry.getValue();int largest=group.stream().mapToInt(c->c.studentCount).max().orElse(0);long suitable=rooms.findAll().stream().filter(r->r.available&&r.capacity>=largest).count();if(suitable==0||group.size()>=suitable){String key=weekdays[day-1]+" "+entry.getKey();insights.put(key,Map.of("day",weekdays[day-1],"interval",entry.getKey(),"classes",group.size(),"largestClass",largest,"suitableRooms",suitable,"additionalClassesBeforeShortage",Math.max(0,(int)suitable-group.size()),"explanation",suitable==0?"No available room can hold the largest class ("+largest+" students).":group.size()+" classes compete for "+suitable+" rooms large enough for up to "+largest+" students."));}}}return Map.of("heatmap",heat,"bottlenecks",insights.values());}
    private boolean overlapsHour(String label,int hour){if(label==null)return false;try{String[] p=label.split("[–-]");int s=LocalTime.parse(p[0].trim()).getHour(),e=LocalTime.parse(p[1].trim()).getHour();return s<=hour&&e>hour;}catch(Exception ignored){return false;}}
    @GetMapping("/benchmark") public Map<String,Object> benchmark(){return benchmarks.run();}
    @GetMapping("/allocations") public List<Map<String,Object>> allocationList(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){List<Map<String,Object>> out=new ArrayList<>();List<Allocation> classRows=allocations.findAll().stream().filter(a->date==null||date.equals(a.date)).toList();for(Allocation a:classRows){Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.id);m.put("sessionId",a.sessionId);m.put("classId",a.classId);m.put("school",a.school);m.put("program",a.program);m.put("division",a.division);m.put("studentCount",a.studentCount);m.put("date",a.date);m.put("timeLabel",a.timeLabel);m.put("assignedRoom",a.assignedRoom);m.put("floor",a.floor);m.put("status",a.status);m.put("reason",a.reason);m.put("demandType","CLASS");m.put("executionMs",a.executionMs);out.add(m);}for(SpaceAssignment a:spaceAssignments.findAll().stream().filter(x->date==null||date.equals(x.date)).toList()){Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.id);m.put("requestId",a.requestId);m.put("classId",a.type+"-"+a.requestId);m.put("school",a.type);m.put("program",a.title);m.put("division",a.requesterName==null?"—":a.requesterName);m.put("studentCount",a.headcount);m.put("date",a.date);m.put("timeLabel",a.timeLabel);m.put("assignedRoom",a.assignedRoom);m.put("floor",a.floor);m.put("status",a.status);m.put("reason",a.reason);m.put("demandType",a.type);m.put("executionMs",a.executionMs);out.add(m);}return out;}
    @GetMapping("/analytics") public Map<String,Object> analytics(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate date){List<ClassSession> ss=sessions.findAll().stream().filter(s->date==null||s.date.equals(date)).toList();Set<Long> ids=ss.stream().map(s->s.id).collect(Collectors.toSet());List<Allocation> aa=allocations.findBySessionIdIn(ids);List<SpaceAssignment> sa=spaceAssignments.findAll().stream().filter(a->date==null||date.equals(a.date)).toList();long done=aa.stream().filter(a->"Allocated".equals(a.status)).count(),spaceDone=sa.stream().filter(a->"Allocated".equals(a.status)).count();long conflict=0;for(int i=0;i<ss.size();i++)for(int j=i+1;j<ss.size();j++)if(ss.get(i).date.equals(ss.get(j).date)&&ss.get(i).startTime.isBefore(ss.get(j).endTime)&&ss.get(j).startTime.isBefore(ss.get(i).endTime))conflict++;
        Map<String,Long> used=new HashMap<>();aa.stream().filter(a->"Allocated".equals(a.status)).forEach(a->used.merge(a.assignedRoom,1L,Long::sum));sa.stream().filter(a->"Allocated".equals(a.status)&&a.assignedRoom!=null).forEach(a->used.merge(a.assignedRoom,1L,Long::sum));List<Map<String,Object>> top=used.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(5).map(e->Map.<String,Object>of("room",e.getKey(),"classes",e.getValue())).toList();Map<Integer,Long> floorUse=new HashMap<>();aa.stream().filter(a->"Allocated".equals(a.status)).forEach(a->floorUse.merge(a.floor,1L,Long::sum));sa.stream().filter(a->"Allocated".equals(a.status)).forEach(a->floorUse.merge(a.floor,1L,Long::sum));List<Map<String,Object>> floors=IntStream.rangeClosed(1,7).mapToObj(f->Map.<String,Object>of("floor",f,"availableRooms",rooms.findAll().stream().filter(r->r.floor==f&&r.available).count(),"allocatedClasses",floorUse.getOrDefault(f,0L))).toList();double seats=rooms.findAll().stream().filter(r->r.available).mapToInt(r->r.capacity).sum();double usedSeats=aa.stream().filter(a->"Allocated".equals(a.status)).mapToInt(a->a.studentCount).sum()+sa.stream().filter(a->"Allocated".equals(a.status)).mapToInt(a->a.headcount).sum();long periods=periodsCount(date,ss,sa);long dates=date==null?java.util.stream.Stream.concat(ss.stream().map(x->x.date),sa.stream().map(x->x.date)).distinct().count():1;double denominator=seats*Math.max(1,periods)*Math.max(1,dates);double execution=Math.max(aa.stream().mapToDouble(a->a.executionMs).max().orElse(0),sa.stream().mapToDouble(a->a.executionMs).max().orElse(0));Map<String,Object> report=new LinkedHashMap<>();report.put("totalClasses",ss.size());report.put("allocated",done);report.put("unallocated",Math.max(0,ss.size()-done));report.put("coverage",ss.isEmpty()?0:100.0*done/ss.size());report.put("spaceRequests",sa.size());report.put("spaceAllocated",spaceDone);report.put("events",sa.stream().filter(a->"EVENT".equals(a.type)).count());report.put("studyRequests",sa.stream().filter(a->"STUDY".equals(a.type)).count());report.put("utilization",denominator==0?0:100.0*usedSeats/denominator);report.put("conflicts",conflict);report.put("executionMs",execution);report.put("topRooms",top);report.put("floors",floors);report.put("medianClassSize",AllocationAlgorithms.median(ss,x->x.studentCount));report.put("medianRoomCapacity",AllocationAlgorithms.median(rooms.findAll(),r->r.capacity));List<Map<String,Object>> bottlenecks=new ArrayList<>();aa.stream().filter(a->"Unallocated".equals(a.status)||"Invalid".equals(a.status)).forEach(a->bottlenecks.add(Map.of("classId",a.classId,"reason",a.reason==null?"No reason supplied":a.reason)));sa.stream().filter(a->"Unallocated".equals(a.status)).forEach(a->bottlenecks.add(Map.of("classId",a.type+"-"+a.requestId,"reason",a.reason==null?"No room available":a.reason)));report.put("bottlenecks",bottlenecks);return report;}
    private long periodsCount(LocalDate date,List<ClassSession> classes,List<SpaceAssignment> requests){Set<Long> ids=new HashSet<>();classes.forEach(c->periods.findAll().stream().filter(p->p.startTime.equals(c.startTime)&&p.endTime.equals(c.endTime)).forEach(p->ids.add(p.id)));requests.forEach(r->{if(r.periodId!=null)ids.add(r.periodId);});return date==null?Math.max(1,periods.findAll().stream().filter(p->p.active).count()):Math.max(1,ids.size());}
    @GetMapping("/template") public ResponseEntity<byte[]> template(){String csv="classId,school,program,academicYear,division,studentCount,date,startTime,endTime\n";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=campusos-timetable-template.csv").contentType(MediaType.parseMediaType("text/csv")).body(csv.getBytes(StandardCharsets.UTF_8));}
    @PostMapping(value="/import",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> importCsv(@RequestParam("file")MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("Choose a CSV file first.");List<List<String>> rows=parseCsv(new String(file.getBytes(),StandardCharsets.UTF_8));if(rows.isEmpty())throw new IllegalArgumentException("CSV is empty.");List<String> header=rows.get(0).stream().map(x->x.trim().toLowerCase()).toList();List<String> required=List.of("classid","school","program","academicyear","division","studentcount","date","starttime","endtime");List<String> missing=required.stream().filter(x->!header.contains(x)).toList();if(!missing.isEmpty())throw new IllegalArgumentException("Required columns missing: "+String.join(", ",missing));List<String> errors=new ArrayList<>();List<ClassSession> accepted=new ArrayList<>();Set<String> seen=new HashSet<>();int line=1;for(List<String> row:rows.subList(1,rows.size())){line++;if(row.stream().allMatch(String::isBlank))continue;try{Map<String,String> m=new HashMap<>();for(int i=0;i<header.size();i++)m.put(header.get(i),i<row.size()?row.get(i).trim():"");for(String key:required)if(m.getOrDefault(key,"").isBlank())throw new IllegalArgumentException("missing "+key);ClassSession s=new ClassSession();s.classId=m.get("classid");s.school=m.get("school").toUpperCase();s.program=m.get("program");s.academicYear=Integer.parseInt(m.get("academicyear"));s.division=m.get("division");s.studentCount=Integer.parseInt(m.get("studentcount"));s.date=LocalDate.parse(m.get("date"));s.startTime=LocalTime.parse(m.get("starttime"));s.endTime=LocalTime.parse(m.get("endtime"));validateSession(s);String key=s.classId+"|"+s.date+"|"+s.startTime+"|"+s.division;if(!seen.add(key)||sessions.existsByClassIdAndDateAndStartTimeAndDivision(s.classId,s.date,s.startTime,s.division))throw new IllegalArgumentException("duplicate record");accepted.add(s);}catch(Exception ex){errors.add("Row "+line+": "+(ex.getMessage()==null?"invalid value":ex.getMessage()));}}
        sessions.saveAll(accepted);return Map.of("imported",accepted.size(),"rejected",errors.size(),"errors",errors,"message",errors.isEmpty()?"All valid records imported.":"Valid rows were imported; review every rejected row below.");}
    private List<List<String>> parseCsv(String csv){List<List<String>> out=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder field=new StringBuilder();boolean quoted=false;for(int i=0;i<csv.length();i++){char c=csv.charAt(i);if(c=='"'){if(quoted&&i+1<csv.length()&&csv.charAt(i+1)=='"'){field.append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){row.add(field.toString());field.setLength(0);}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<csv.length()&&csv.charAt(i+1)=='\n')i++;row.add(field.toString());field.setLength(0);out.add(row);row=new ArrayList<>();}else field.append(c);}if(field.length()>0||!row.isEmpty()){row.add(field.toString());out.add(row);}return out;}
}
